function renderLines(){if(!db)return;$('#linecount').textContent=`${db.routes.size} lines`;if(lineId){$('#line-list').hidden=true;$('#line-detail').hidden=false;return}$('#line-list').hidden=false;$('#line-detail').hidden=true;let q=norm($('#line-search').value),routes=[...db.routes.values()].sort((a,b)=>line(a).localeCompare(line(b),'en',{numeric:true})).filter(r=>norm(line(r)).includes(q));$('#line-list').innerHTML=routes.length?routes.map(r=>{let heads=[...new Set((routeTrips.get(r.route_id)||[]).map(t=>name(t.trip_headsign)))].filter(Boolean);return `<button class="linecard" data-line="${r.route_id}"><strong>${esc(line(r))}</strong><span>${esc(heads.slice(0,2).join(' / ')||'View stops and live buses')}</span></button>`}).join(''):'<div class="empty">No matching bus numbers.</div>'}
