document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.stop)selectStop(b.dataset.stop);else if(b.dataset.line)openLine(b.dataset.line);else if(b.hasAttribute('data-back-stops')){stopId=null;chosenLines.clear();renderHome();updateVehicles()}else if(b.hasAttribute('data-back-lines')){lineId=null;lineMap?.remove();lineMap=null;vehicleMarkers.line=[];renderLines()}else if(b.dataset.save){saved.has(b.dataset.save)?saved.delete(b.dataset.save):saved.add(b.dataset.save);localStorage.setItem('tuka-saved',JSON.stringify([...saved]));renderHome()}else if(b.dataset.filter){chosenLines.has(b.dataset.filter)?chosenLines.delete(b.dataset.filter):chosenLines.add(b.dataset.filter);renderHome();updateVehicles()}else if(b.hasAttribute('data-direction')){direction=+b.dataset.direction;drawLineDetail()}else if(b.hasAttribute('data-place'))chooseDestination(placeChoices[+b.dataset.place])});
