initHome();
try{db=await load();stopIndex=new Map(db.stops.map(s=>[s.id,s]));for(let t of db.trips.values()){if(!routeTrips.has(t.route_id))routeTrips.set(t.route_id,[]);routeTrips.get(t.route_id).push(t)}updateStopLayer();renderLines();await refresh();renderHome();setInterval(()=>{if(!document.hidden)refresh()},30000)}catch(e){$('#feedstatus').textContent='JSP data unavailable';$('#error').hidden=false;$('#error').innerHTML='Could not load the JSP schedule. Check your connection and <button class="textbtn" onclick="location.reload()">try again</button>.';console.error(e)}
